/* ============================================
   OpenLearnHub — Global Styles
   ============================================ */

/* CSS Variables */
:root {
  --primary-dark: #0a0a23;
  --accent-gold: #feac32;
  --link-blue: #002ead;
  --text-body: #1b1b32;
  --text-muted: #6b7280;
  --bg-body: #ffffff;
  --bg-light: #f5f6f7;
  --bg-card: #ffffff;
  --border-color: #e5e7eb;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.12);
  --transition: 0.2s ease;
  --max-width: 1200px;
  --header-height: 64px;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--text-body);
  background: var(--bg-body);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--link-blue);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

ul, ol {
  list-style: none;
}

/* ============================================
   HEADER
   ============================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--primary-dark);
  height: var(--header-height);
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 700;
  font-size: 1.25rem;
  color: #fff;
  white-space: nowrap;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--accent-gold);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.875rem;
  color: var(--primary-dark);
}

.search-bar {
  flex: 1;
  max-width: 420px;
  position: relative;
}

.search-bar input {
  width: 100%;
  padding: 0.5rem 1rem 0.5rem 2.25rem;
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 999px;
  background: rgba(255,255,255,0.08);
  color: #fff;
  font-size: 0.875rem;
  outline: none;
  transition: background var(--transition), border-color var(--transition);
}

.search-bar input::placeholder {
  color: rgba(255,255,255,0.5);
}

.search-bar input:focus {
  background: rgba(255,255,255,0.12);
  border-color: rgba(255,255,255,0.3);
}

.search-bar svg {
  position: absolute;
  left: 0.75rem;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  color: rgba(255,255,255,0.5);
  pointer-events: none;
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.desktop-nav a {
  color: rgba(255,255,255,0.85);
  font-size: 0.9375rem;
  font-weight: 500;
}

.desktop-nav a:hover {
  color: #fff;
  text-decoration: none;
}

.menu-toggle {
  display: none;
  background: none;
  border: none;
  color: #fff;
  cursor: pointer;
  padding: 0.25rem;
}

.mobile-nav {
  display: none;
  background: var(--primary-dark);
  border-top: 1px solid rgba(255,255,255,0.08);
}

.mobile-nav.open {
  display: block;
}

.mobile-nav a {
  display: block;
  padding: 0.875rem 1.5rem;
  color: rgba(255,255,255,0.85);
  font-size: 0.9375rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

.mobile-nav a:hover {
  background: rgba(255,255,255,0.05);
  color: #fff;
  text-decoration: none;
}

/* ============================================
   BANNER
   ============================================ */
.banner {
  background: var(--bg-light);
  border-bottom: 1px solid var(--border-color);
  text-align: center;
  padding: 0.75rem 1rem;
}

.banner a {
  color: var(--text-body);
  font-weight: 600;
  font-size: 0.9375rem;
}

.banner a:hover {
  color: var(--link-blue);
}

/* ============================================
   CONTAINER & SECTIONS
   ============================================ */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 3rem 0;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: var(--text-body);
}

/* ============================================
   ARTICLE CARDS
   ============================================ */
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.article-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
  cursor: pointer;
}

.article-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.article-card .thumbnail {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%);
  overflow: hidden;
}

.article-card .thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.article-card .tag-label {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  background: var(--primary-dark);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.625rem;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.article-card .card-body {
  padding: 1rem;
}

.article-card .card-title {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 0.75rem;
  color: var(--text-body);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.article-card .card-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.article-card .avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: linear-gradient(135deg, #a5b4fc, #6366f1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}

.article-card .author-name {
  font-size: 0.8125rem;
  color: var(--text-body);
  font-weight: 500;
}

.article-card .timestamp {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* Featured Article */
.featured-section {
  padding: 2rem 0 1rem;
}

.featured-card {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 0;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  cursor: pointer;
  transition: box-shadow var(--transition);
}

.featured-card:hover {
  box-shadow: var(--shadow-md);
}

.featured-card .thumbnail {
  position: relative;
  min-height: 280px;
  background: linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%);
}

.featured-card .thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.featured-card .tag-label {
  position: absolute;
  top: 1rem;
  left: 1rem;
  background: var(--primary-dark);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.625rem;
  border-radius: 4px;
  text-transform: uppercase;
}

.featured-card .card-body {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.featured-card .card-title {
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.25;
  margin-bottom: 1.25rem;
  color: var(--text-body);
}

.featured-card .card-meta {
  display: flex;
  align-items: center;
  gap: 0.625rem;
}

.featured-card .avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, #a5b4fc, #6366f1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: #fff;
}

.featured-card .author-name {
  font-size: 0.9375rem;
  font-weight: 600;
}

.featured-card .timestamp {
  font-size: 0.9375rem;
  color: var(--text-muted);
}

/* Load More */
.load-more-wrap {
  text-align: center;
  padding: 2rem 0 1rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
}

.btn-primary {
  background: var(--accent-gold);
  color: var(--primary-dark);
}

.btn-primary:hover {
  background: #e69a2a;
  transform: translateY(-1px);
}

.btn-secondary {
  background: var(--primary-dark);
  color: #fff;
}

.btn-secondary:hover {
  background: #1b1b32;
}

/* ============================================
   TAG PAGES
   ============================================ */
.tag-header {
  padding: 2.5rem 0 1.5rem;
  text-align: center;
}

.tag-header h1 {
  font-size: 2rem;
  font-weight: 800;
  color: var(--text-body);
  margin-bottom: 0.25rem;
}

.tag-header p {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

.popular-tags {
  padding: 1rem 0 2rem;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 2rem;
}

.popular-tags-scroll {
  display: flex;
  gap: 0.75rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
  scrollbar-width: thin;
}

.popular-tags-scroll::-webkit-scrollbar {
  height: 4px;
}

.popular-tags-scroll::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}

.popular-tag {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.5rem 0.875rem;
  background: var(--bg-light);
  border: 1px solid var(--border-color);
  border-radius: 999px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-body);
  white-space: nowrap;
  transition: background var(--transition), border-color var(--transition);
}

.popular-tag:hover {
  background: #fff;
  border-color: var(--accent-gold);
  text-decoration: none;
}

.popular-tag .count {
  color: var(--text-muted);
  font-weight: 400;
}

/* ============================================
   LEARN PAGE
   ============================================ */
.welcome-cta {
  background: var(--bg-light);
  border-bottom: 1px solid var(--border-color);
  padding: 2rem 0;
  text-align: center;
}

.welcome-cta p {
  font-size: 1rem;
  color: var(--text-muted);
}

.welcome-cta a {
  color: var(--link-blue);
  font-weight: 600;
}

.cert-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1rem;
}

.cert-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem 1.25rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  transition: box-shadow var(--transition), border-color var(--transition);
  cursor: pointer;
}

.cert-card:hover {
  box-shadow: var(--shadow-sm);
  border-color: var(--accent-gold);
}

.cert-card .cert-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius);
  background: var(--bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.cert-card .cert-icon svg {
  width: 22px;
  height: 22px;
  color: var(--primary-dark);
}

.cert-card .cert-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-body);
}

/* Challenge & Lists */
.challenge-box {
  background: linear-gradient(135deg, var(--primary-dark), #1b1b32);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
}

.challenge-box h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.challenge-box .links {
  display: flex;
  justify-content: center;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.challenge-box .links a {
  color: var(--accent-gold);
  font-weight: 600;
  font-size: 0.9375rem;
}

.challenge-box .links a:hover {
  color: #ffc04d;
}

.link-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.link-list a {
  display: block;
  padding: 0.625rem 0;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-body);
  border-bottom: 1px solid var(--border-color);
}

.link-list a:hover {
  color: var(--link-blue);
  text-decoration: none;
}

.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.subsection-title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--text-body);
}

/* ============================================
   DONATE PAGE
   ============================================ */
.donate-hero {
  background: var(--bg-light);
  padding: 3rem 0;
  text-align: center;
}

.donate-hero h1 {
  font-size: 2.25rem;
  font-weight: 800;
  margin-bottom: 1rem;
}

.donate-hero p {
  max-width: 640px;
  margin: 0 auto;
  color: var(--text-muted);
  font-size: 1.0625rem;
  line-height: 1.7;
}

.donation-form {
  padding: 2.5rem 0;
}

.donation-card {
  max-width: 520px;
  margin: 0 auto;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-sm);
}

.amount-tabs {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.amount-tab {
  flex: 1;
  padding: 0.75rem;
  text-align: center;
  font-size: 1rem;
  font-weight: 700;
  border: 2px solid var(--border-color);
  border-radius: var(--radius);
  background: #fff;
  color: var(--text-body);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
}

.amount-tab:hover {
  border-color: var(--accent-gold);
}

.amount-tab.active {
  border-color: var(--accent-gold);
  background: rgba(254, 172, 50, 0.08);
}

.donation-desc {
  font-size: 0.9375rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
  line-height: 1.6;
}

.donation-desc strong {
  color: var(--text-body);
}

.donate-btn-wrap {
  margin-bottom: 0.75rem;
}

.donate-btn-wrap .btn {
  width: 100%;
  padding: 1rem;
  font-size: 1.0625rem;
}

.donation-sub {
  text-align: center;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.donation-sub a {
  color: var(--text-muted);
  text-decoration: underline;
}

/* Benefits & Initiatives */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.5rem;
}

.benefit-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 1.5rem;
  text-align: center;
}

.benefit-card .icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 0.75rem;
  background: var(--bg-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.benefit-card .icon svg {
  width: 24px;
  height: 24px;
  color: var(--accent-gold);
}

.benefit-card p {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-body);
}

.initiatives-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1rem;
}

.initiative-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 1rem;
  background: var(--bg-light);
  border-radius: var(--radius);
}

.initiative-item svg {
  width: 20px;
  height: 20px;
  color: var(--accent-gold);
  flex-shrink: 0;
  margin-top: 2px;
}

.initiative-item span {
  font-size: 0.9375rem;
  font-weight: 500;
}

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 1.5rem;
}

.stat-card {
  text-align: center;
  padding: 1.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
}

.stat-card .stat-number {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--accent-gold);
  margin-bottom: 0.25rem;
}

.stat-card .stat-label {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* FAQ Accordion */
.faq-list {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.faq-item {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--bg-card);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.25rem;
  background: none;
  border: none;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-body);
  cursor: pointer;
  text-align: left;
}

.faq-question svg {
  width: 18px;
  height: 18px;
  color: var(--text-muted);
  transition: transform var(--transition);
  flex-shrink: 0;
}

.faq-item.open .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding: 0 1.25rem 1rem;
}

.faq-answer p {
  font-size: 0.9375rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* ============================================
   FOOTER
   ============================================ */
.site-footer {
  background: var(--primary-dark);
  color: rgba(255,255,255,0.7);
  padding: 3rem 0 2rem;
  margin-top: 2rem;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.footer-mission {
  font-size: 0.9375rem;
  line-height: 1.7;
  max-width: 720px;
  margin-bottom: 2rem;
}

.footer-section {
  margin-bottom: 2rem;
}

.footer-section h4 {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #fff;
  margin-bottom: 0.75rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.5rem;
}

.footer-links a {
  color: rgba(255,255,255,0.7);
  font-size: 0.875rem;
}

.footer-links a:hover {
  color: #fff;
  text-decoration: underline;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 1.5rem;
  margin-top: 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.5);
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 992px) {
  .article-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .featured-card {
    grid-template-columns: 1fr;
  }

  .featured-card .thumbnail {
    min-height: 200px;
  }

  .two-col {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .article-grid {
    grid-template-columns: 1fr;
  }

  .desktop-nav {
    display: none;
  }

  .menu-toggle {
    display: block;
  }

  .search-bar {
    display: none;
  }

  .featured-card .card-title {
    font-size: 1.25rem;
  }

  .featured-card .card-body {
    padding: 1.25rem;
  }

  .donate-hero h1 {
    font-size: 1.625rem;
  }

  .amount-tabs {
    flex-wrap: wrap;
  }

  .amount-tab {
    min-width: calc(50% - 0.25rem);
  }

  .benefits-grid,
  .stats-grid,
  .initiatives-list {
    grid-template-columns: 1fr;
